    logic                          commits_isCommit;
    logic [COMMIT_W-1:0]           commits_commitValid;
    robptr_t [COMMIT_W-1:0]        commits_robIdx;
    commit_to_ftq_t [COMMIT_W-1:0] commits_info;
    logic                          rabCommits_isCommit;
    logic                          rabCommits_isWalk;
    logic [RAB_W-1:0]              rabCommits_commitValid;
    logic [RAB_W-1:0]              rabCommits_v0Wen;
    logic [RAB_W-1:0]              rabCommits_vecWen;
    logic                          enq_canAccept;
    logic                          enq_canAcceptForDispatch;
    logic                          enq_isEmpty;
    logic                          exception_valid;
    logic [6:0]                    retiredInstr;
    logic                          error0;
  } rob_out_t;

  typedef struct packed {
    logic                          redirect_valid;         // s1_s3（Rob.io.redirect）
    robptr_t                       redirect_robIdx;
    logic                          redirect_level;
    logic                          redirect_isMisPred;
    enq_req_t [DECODE_W-1:0]       enq_req;
    logic                          snpt_useSnpt;
    logic [1:0]                    snpt_snptSelect;
    logic                          snpt_snptDeq;
    logic [SNPT_N-1:0]             snpt_flushVec;
    logic                          vstartIsZero;
    logic                          wfi_enable;
    wb_lane_t [WB_N-1:0]           writeback;              // delayedNotFlushedWriteBack
    logic [WB_N-1:0]               exuWriteback_valid;     // delayedWriteBack.valid（bits 同上）
    logic [WB_N-1:0][WB_NUM_W-1:0] writebackNums;
    logic [WB_N-1:0]               writebackNeedFlush;     // 按 lane 编号；wrapper 只接 need_exc_gen 的口
  } rob_in_t;

  typedef struct packed {
    logic              stage2_valid;
    redirect_t         stage2_bits;
    logic [1:0]        stage2oldestOH;
  } redirectgen_out_t;

  typedef struct packed {
    logic              oldestExuRedirect_valid;
    exu_redirect_t     oldestExuRedirect_bits;
    logic              oldestExuRedirectIsCSR;
    addr_trans_type_t  instrAddrTransType;
    predecode_t        oldestExuOutPredecode;
    logic              loadReplay_valid;
    mem_violation_t    loadReplay_bits;
    logic [VADDR_W-1:0] loadReplay_pc;          // loadReplay.bits.cfiUpdate.pc = .target
    logic [VADDR_W-1:0] memPredPcRead_data;
    logic              robFlush_valid;
    rob_flush_t        robFlush_bits;
  } redirectgen_in_t;

  typedef struct packed {
    enq_req_t [DECODE_W-1:0] enqRob_req;
  } dispatch_out_t;

  typedef struct packed {
    logic [DECODE_W-1:0] renameIn_valid;
    logic                enqRob_canAccept;
    logic                enqRob_isEmpty;
    logic                singleStep;
    logic [DECODE_W-1:0][34:0] renameIn_fuType;    // 融合改写后的 fuType/fuOpType（Q4）
    logic [DECODE_W-1:0][8:0]  renameIn_fuOpType;
  } dispatch_in_t;

  typedef struct packed {
    logic [DECODE_W-1:0]            in_ready;
    logic [DECODE_W-1:0]            out_valid;
    logic [DECODE_W-1:0][EXC_N-1:0] out_exceptionVec;
    logic [DECODE_W-1:0][3:0]       out_trigger;
  } decode_out_t;

  typedef struct packed {
    static_inst_valid_t [DECODE_W-1:0] in;
    logic                              redirect;
    logic [DECODE_W-2:0]               fusion;
    logic                              backendCanAccept;
    csr_ctrl_t                         csrCtrl;    // RegNext(io.csrCtrl)
  } decode_in_t;

  // decode→rename 流水缓冲（PipelineConnectPipe）出口里核要看的字段
  typedef struct packed {
    logic        out_valid;
    logic        in_ready;
    logic [5:0]  ftqPtr_value;
    logic [3:0]  ftqOffset;
    logic        isMove;
    logic [34:0] fuType;
    logic [8:0]  fuOpType;
    logic [3:0]  srcType_1;
    logic [5:0]  lsrc_1;
    logic [3:0]  selImm;
    logic [2:0]  commitType;
    logic [9:0]  foldpc;
  } pipe_out_t;

  typedef struct packed {
    logic        valid;
    logic        fuType_valid;
    logic        fuOpType_valid;
    logic [8:0]  fuOpType_bits;
    logic        src2Type_valid;
    logic        lsrc2_valid;
    logic [5:0]  lsrc2_bits;
    logic        selImm_valid;
    logic [3:0]  selImm_bits;
  } fusion_out_lane_t;

  typedef struct packed {
    fusion_out_lane_t [DECODE_W-2:0] out;
    logic [DECODE_W-1:0]             clear;    // bit 0 不存在（第 0 路不会被融合掉），恒 0
  } fusion_out_t;

  typedef struct packed {
    logic                disableFusion;
    logic [DECODE_W-1:0] in_valid;
  } fusion_in_t;

  typedef struct packed {
    logic [DECODE_W-1:0]          out_valid;
    logic [DECODE_W-1:0]          out_snapshot;
  } rename_out_t;

  // rename 入口被融合改写的字段（lane 0..4 改写，lane 5 只有 valid）
  typedef struct packed {
    logic        valid;
    logic [34:0] fuType;
    logic [8:0]  fuOpType;
    logic [3:0]  srcType_1;
    logic [5:0]  lsrc_1;
    logic [3:0]  selImm;
    logic [2:0]  commitType;
  } rename_in_lane_t;

  typedef struct packed {
    logic                          redirect_valid;   // s1_s3
    robptr_t                       redirect_robIdx;
    logic                          redirect_level;
    logic                          redirect_debugIsCtrl;
    logic                          redirect_debugIsMemVio;
    rename_in_lane_t [DECODE_W-1:0] in;
    logic                          snpt_useSnpt;
    logic [1:0]                    snpt_snptSelect;
    logic                          snpt_snptDeq;
    logic [SNPT_N-1:0]             snpt_flushVec;
    logic                          snptLastEnq_valid;
    robptr_t                       snptLastEnq_bits;
    logic                          snptIsFull;
    logic                          singleStep;
  } rename_in_t;

  typedef struct packed {
    logic [RAB_W-1:0][PREG_W-1:0] v0_old_pdest;
    logic [RAB_W-1:0][PREG_W-1:0] vec_old_pdest;
  } rat_out_t;

  typedef struct packed {
    logic                redirect;         // s1_s3.valid
    logic [DECODE_W-1:0] renameUpdates_valid;
    logic                snpt_snptEnq;
    logic                snpt_snptDeq;
    logic                snpt_useSnpt;
    logic [1:0]          snpt_snptSelect;
    logic [SNPT_N-1:0]   snpt_flushVec;    // ★RAT 收的是没打拍的 flushVec★
  } rat_in_t;

  typedef struct packed {
    logic [SNPT_N-1:0]        valids;
    snapshot_t [SNPT_N-1:0]   snapshots;
    snptptr_t                 enqPtr;
    snptptr_t                 deqPtr;
  } snpt_out_t;

  typedef struct packed {
    logic              enq;
    logic              deq;
    logic              redirect;
    logic [SNPT_N-1:0] flushVec;   // 打过一拍的 flushVecNext
  } snpt_in_t;

  typedef struct packed {
    logic [PCMEM_RD_N-1:0][VADDR_W-1:0] rdata_startAddr;
  } pcmem_out_t;

  typedef struct packed {
    logic [PCMEM_RD_N-1:0]      ren;
    logic [PCMEM_RD_N-1:0][5:0] raddr;
    logic                       wen;
    logic [5:0]                 waddr;
    logic [VADDR_W-1:0]         wdata_startAddr;
  } pcmem_in_t;

  typedef struct packed {
    logic [MDP_N-1:0]      mdpFoldPcVecVld;
    logic [MDP_N-1:0][9:0] mdpFlodPcVec;
  } memctrl_in_t;

  typedef struct packed {
    logic [DECODE_W-1:0] in_ready;   // renamePipeDispatch.io_in_N_ready
  } pgc_out_t;

  typedef struct packed {
    logic in0_snapshot;               // renamePipeDispatch.io_in_0_bits_snapshot
  } pgc_in_t;

  typedef struct packed {
    logic [3:0]                       block0_itype;          // trace.toEncoder.blocks(0).tracePipe.itype
    logic [TRACE_GRP-1:0]             toPcMem_valid;
    logic [TRACE_GRP-1:0][5:0]        toPcMem_ftqIdx_value;
  } trace_out_t;

  typedef struct packed {
    logic s5_flushFromRobValidAhead;  // DelayN_15(s1_robFlushRedirect.valid, 4)
    logic s5_csrIsTrap;               // DelayN_15(rob.io.exception.valid, 4)
  } delay_out_t;

endpackage

// ============================================================================
// 可读核：CtrlBlock 的全部 glue 逻辑
// ============================================================================
module xs_CtrlBlock_core
  import ctrlblock_pkg::*;
(
  input  logic              clock,
  input  logic              reset,
  // 顶层 IO 里核真用到的部分
  input  cb_in_t            io_in,
  output cb_out_t           io_out,
  // child 出口 → 核；核 → child 入口
  input  rob_out_t          rob_o,
  output rob_in_t           rob_i,
  input  redirectgen_out_t  redirectgen_o,
  output redirectgen_in_t   redirectgen_i,
  input  dispatch_out_t     dispatch_o,
  output dispatch_in_t      dispatch_i,
  input  decode_out_t       decode_o,
  output decode_in_t        decode_i,
  input  pipe_out_t         pipe_o [DECODE_W],     // 6 个 decode→rename 流水缓冲
  output logic              pipe_isFlush,
  input  fusion_out_t       fusion_o,
  output fusion_in_t        fusion_i,
  input  rename_out_t       rename_o,
  output rename_in_t        rename_i,
  input  rat_out_t          rat_o,
  output rat_in_t           rat_i,
  input  snpt_out_t         snpt_o,
  output snpt_in_t          snpt_i,
  input  pcmem_out_t        pcmem_o,
  output pcmem_in_t         pcmem_i,
  output memctrl_in_t       memctrl_i,
  input  pgc_out_t          pgc_o,
  output pgc_in_t           pgc_i,
  input  delay_out_t        delay_o,
  output logic              delay_s5flush_in,      // s5_flushFromRobValidAhead_delay.io_in
  input  trace_out_t        trace_o,
  input  logic [PERF_N-1:0][5:0] perf_in           // decode/rename/dispatch/rob 的 perf 事件（golden io_perf 顺序）
);

  // --------------------------------------------------------------------------
  // 1. 重定向流水：s0 Rob.flushOut → s1 → s1_s3（与 RedirectGenerator.stage2 二选一）→ s2_s4 → s3_s5
  // --------------------------------------------------------------------------
  logic        s1_rob_flush_valid;        // GatedValidRegNext(rob.flushOut.valid)
  rob_flush_t  s1_rob_flush_bits;         // RegEnable(rob.flushOut.bits)
  logic [3:0]  s1_rob_flush_pc_offset;    // golden 另有一份 ftqOffset 寄存器专供算 flush pc（s1_robFlushPc_r）
  always_ff @(posedge clock or posedge reset)
    if (reset) s1_rob_flush_valid <= 1'b0;
    else       s1_rob_flush_valid <= rob_o.flushOut_valid;
  always_ff @(posedge clock)
    if (rob_o.flushOut_valid) begin
      s1_rob_flush_bits      <= rob_o.flushOut_bits;
      s1_rob_flush_pc_offset <= rob_o.flushOut_bits.ftqOffset;
    end

  // s1_robFlushPc = pcMem[robFlush 读口].startAddr + (ftqOffset << 1)
  logic [VADDR_W-1:0] s1_rob_flush_pc;
  assign s1_rob_flush_pc = pcmem_o.rdata_startAddr[PCRD_ROBFLUSH] + VADDR_W'({s1_rob_flush_pc_offset, 1'b0});

  // s1_s3：Rob flush 优先；Q1：Rob flush 没有的字段取 0（golden 逐字段 `s1v ? 0 : stage2.x`）
  function automatic redirect_t extend_rob_flush(rob_flush_t f);
    redirect_t r;
    r = '0;
    r.isRVC          = f.isRVC;
    r.robIdx         = f.robIdx;
    r.ftqIdx         = f.ftqIdx;
    r.ftqOffset      = f.ftqOffset;
    r.level          = f.level;
    r.satpFlush      = f.satpFlush;
    r.isVlsException = f.isVlsException;
    r.interrupt      = 1'b1;   // Rob.flushOut.bits.interrupt 恒为 true（golden：s2_s4.interrupt <= s1v | stage2.interrupt）
    return r;
  endfunction
  logic      s1_s3_valid;
  redirect_t s1_s3_bits;
  assign s1_s3_valid = s1_rob_flush_valid ? s1_rob_flush_valid : redirectgen_o.stage2_valid;
  assign s1_s3_bits  = s1_rob_flush_valid ? extend_rob_flush(s1_rob_flush_bits) : redirectgen_o.stage2_bits;

  // 前端 flush 尚未真正发出前，decode 一直看到 redirect（s2_s4_pendingRedirectValid）
  logic pending_redirect_q, to_ftq_redirect_valid_q;
  always_ff @(posedge clock or posedge reset)
    if (reset) begin
      pending_redirect_q      <= 1'b0;
      to_ftq_redirect_valid_q <= 1'b0;
    end else begin
      pending_redirect_q      <= s1_s3_valid | (~to_ftq_redirect_valid_q & pending_redirect_q);
      to_ftq_redirect_valid_q <= io_out.toFtq.redirect_valid;
    end

  // s2_s4 = RegNextWithEnable(s1_s3)；s3_s5 = RegNextWithEnable(s2_s4)（golden 只保留 robIdx/level）
  logic      s2_s4_valid;
  redirect_t s2_s4_bits;
  logic      s3_s5_valid;
  robptr_t   s3_s5_robIdx;
  logic      s3_s5_level;
  always_ff @(posedge clock or posedge reset)
    if (reset) begin
      s2_s4_valid <= 1'b0;
      s3_s5_valid <= 1'b0;
    end else begin
      s2_s4_valid <= s1_s3_valid;
      s3_s5_valid <= s2_s4_valid;
    end
  always_ff @(posedge clock) begin
    if (s1_s3_valid) s2_s4_bits <= s1_s3_bits;
    if (s2_s4_valid) begin
      s3_s5_robIdx <= s2_s4_bits.robIdx;
      s3_s5_level  <= s2_s4_bits.level;
    end
  end

  redirect_lite_t s1_s3_lite, s2_s4_lite, s3_s5_lite, oldest_lite;
  assign s1_s3_lite = '{valid: s1_s3_valid, robIdx: s1_s3_bits.robIdx, level: s1_s3_bits.level};
  assign s2_s4_lite = '{valid: s2_s4_valid, robIdx: s2_s4_bits.robIdx, level: s2_s4_bits.level};
  assign s3_s5_lite = '{valid: s3_s5_valid, robIdx: s3_s5_robIdx,      level: s3_s5_level};
  // findOldestRedirect(findOldestRedirect(s2_s4, s3_s5), s1_s3)：写回压缩计数用的"最老重定向"
  assign oldest_lite = oldest_redirect(oldest_redirect(s2_s4_lite, s3_s5_lite), s1_s3_lite);

  // 对外广播
  assign io_out.redirect_valid          = s1_s3_valid;
  assign io_out.redirect_robIdx         = s1_s3_bits.robIdx;
  assign io_out.redirect_level          = s1_s3_bits.level;
  assign io_out.redirect_isVlsException = s1_s3_bits.isVlsException;
  assign io_out.flush_valid             = s2_s4_valid;
  assign io_out.flush_bits              = s2_s4_bits;
  assign pipe_isFlush                   = s1_s3_valid | pending_redirect_q;   // 6 个 decode→rename 缓冲的 isFlush
  assign rob_i.redirect_valid           = s1_s3_valid;
  assign rob_i.redirect_robIdx          = s1_s3_bits.robIdx;
  assign rob_i.redirect_level           = s1_s3_bits.level;
  assign rob_i.redirect_isMisPred       = s1_s3_bits.cfiUpdate.isMisPred;
  assign rename_i.redirect_valid        = s1_s3_valid;
  assign rename_i.redirect_robIdx       = s1_s3_bits.robIdx;
  assign rename_i.redirect_level        = s1_s3_bits.level;
  assign rename_i.redirect_debugIsCtrl  = s1_s3_bits.debugIsCtrl;
  assign rename_i.redirect_debugIsMemVio= s1_s3_bits.debugIsMemVio;
  assign rat_i.redirect                 = s1_s3_valid;
  assign snpt_i.redirect                = s1_s3_valid;
  assign redirectgen_i.robFlush_valid   = s1_rob_flush_valid;
  assign redirectgen_i.robFlush_bits    = s1_rob_flush_bits;
  assign delay_s5flush_in               = s1_rob_flush_valid;
  assign io_out.exception_pc            = s1_rob_flush_pc;   // io.robio.exception.bits.pc := s1_robFlushPc

  // --------------------------------------------------------------------------
  // 2. 写回打拍与压缩：27 路 ExuOutput 各打一拍，valid 过滤掉被更老重定向冲掉的
  // --------------------------------------------------------------------------
  // 被 s1_s3 或 s2_s4 冲掉（delayedNotFlushedWriteBack / exuRedirects 用）
  logic [WB_N-1:0] wb_killed;
  // 被"三级里最老的那个重定向"冲掉（writebackNums 用）
  logic [WB_N-1:0] wb_killed_by_oldest;
  for (genvar i = 0; i < WB_N; i++) begin : g_wb_kill
    assign wb_killed[i] = rob_need_flush(io_in.wb[i].bits.robIdx, s1_s3_lite.valid, s1_s3_lite.robIdx, s1_s3_lite.level)
                        | rob_need_flush(io_in.wb[i].bits.robIdx, s2_s4_lite.valid, s2_s4_lite.robIdx, s2_s4_lite.level);
    assign wb_killed_by_oldest[i] = rob_need_flush(io_in.wb[i].bits.robIdx, oldest_lite.valid, oldest_lite.robIdx, oldest_lite.level);
  end

  for (genvar i = 0; i < WB_N; i++) begin : g_wb
    localparam wb_lane_shape_t L = WB_LANE[i];
    wire exu_output_t bits;         // 打拍后的 payload；没保留的字段接 0
    exu_output_t in_bits;
    logic        in_valid;
    assign in_bits  = io_in.wb[i].bits;
    assign in_valid = io_in.wb[i].valid;

    // exuWriteback.valid = RegNext(valid)；writeback.valid = RegNext(valid & ~killed)
    logic exu_valid_q;
    always_ff @(posedge clock or posedge reset)
      if (reset) exu_valid_q <= 1'b0; else exu_valid_q <= in_valid;
    assign rob_i.exuWriteback_valid[i] = exu_valid_q;
    if (L.has_valid) begin : g_valid
      logic valid_q;
      always_ff @(posedge clock or posedge reset)
        if (reset) valid_q <= 1'b0; else valid_q <= in_valid & ~wb_killed[i];
      assign rob_i.writeback[i].valid = valid_q;
    end else begin : g_novalid
      assign rob_i.writeback[i].valid = 1'b0;
    end

    // data_0..data_5：每段宽度按 golden（整数口 64 位、向量口 128 位、没有则 0）
    for (genvar k = 0; k < 6; k++) begin : g_data
      if (L.data_w[k] != 0) begin : g_y
        logic [L.data_w[k]-1:0] q;
        always_ff @(posedge clock) if (in_valid) q <= in_bits.data[k][L.data_w[k]-1:0];
        assign bits.data[k] = 128'(q);
      end else begin : g_n
        assign bits.data[k] = '0;
      end
    end

    // 基本字段 + Q6：每路自己的 GTimer 计数器作 writebackTime
    if (L.has_base) begin : g_base
      logic [7:0]      robidx_value_q;
      logic [XLEN-1:0] enqRsTime_q, selectTime_q, issueTime_q;
      logic [XLEN-1:0] gtimer_q;
      always_ff @(posedge clock) if (in_valid) begin
        robidx_value_q <= in_bits.robIdx.value;
        enqRsTime_q    <= in_bits.debugInfo.enqRsTime;
        selectTime_q   <= in_bits.debugInfo.selectTime;
        issueTime_q    <= in_bits.debugInfo.issueTime;
      end
      always_ff @(posedge clock or posedge reset)
        if (reset) gtimer_q <= '0; else gtimer_q <= gtimer_q + 64'h1;
      assign bits.robIdx.value          = robidx_value_q;
      assign bits.debugInfo.enqRsTime   = enqRsTime_q;
      assign bits.debugInfo.selectTime  = selectTime_q;
      assign bits.debugInfo.issueTime   = issueTime_q;
      assign bits.debugInfo.writebackTime = gtimer_q;
    end else begin : g_std   // std 口（lane 25/26）只保留 robIdx.value
      logic [7:0] robidx_value_q;
      always_ff @(posedge clock) if (in_valid) robidx_value_q <= in_bits.robIdx.value;
      assign bits.robIdx.value          = robidx_value_q;
      assign bits.debugInfo.enqRsTime   = '0;
      assign bits.debugInfo.selectTime  = '0;
      assign bits.debugInfo.issueTime   = '0;
      assign bits.debugInfo.writebackTime = '0;
    end

    if (L.has_robidx_flag) begin : g_flag
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.robIdx.flag;
      assign bits.robIdx.flag = q;
    end else begin : g_noflag
      assign bits.robIdx.flag = 1'b0;
    end

    if (L.pdest_w != 0) begin : g_pdest
      logic [L.pdest_w-1:0] q; always_ff @(posedge clock) if (in_valid) q <= in_bits.pdest[L.pdest_w-1:0];
      assign bits.pdest = PREG_W'(q);
    end else begin : g_nopdest
      assign bits.pdest = '0;
    end

    if (L.has_intwen) begin : g_intwen
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.intWen;
      assign bits.intWen = q;
    end else begin : g_nointwen
      assign bits.intWen = 1'b0;
    end
    if (L.has_fpwen) begin : g_fpwen
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.fpWen;
      assign bits.fpWen = q;
    end else begin : g_nofpwen
      assign bits.fpWen = 1'b0;
    end
    if (L.has_vecwen) begin : g_vecwen
      logic vec_q, v0_q;
      always_ff @(posedge clock) if (in_valid) begin vec_q <= in_bits.vecWen; v0_q <= in_bits.v0Wen; end
      assign bits.vecWen = vec_q;
      assign bits.v0Wen  = v0_q;
    end else begin : g_novecwen
      assign bits.vecWen = 1'b0;
      assign bits.v0Wen  = 1'b0;
    end
    if (L.has_vlwen) begin : g_vlwen
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.vlWen;
      assign bits.vlWen = q;
    end else begin : g_novlwen
      assign bits.vlWen = 1'b0;
    end
    if (L.has_vxsat) begin : g_vxsat
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.vxsat;
      assign bits.vxsat = q;
    end else begin : g_novxsat
      assign bits.vxsat = 1'b0;
    end
    if (L.has_fflags) begin : g_fflags
      logic [4:0] fflags_q; logic wflags_q;
      always_ff @(posedge clock) if (in_valid) begin fflags_q <= in_bits.fflags; wflags_q <= in_bits.wflags; end
      assign bits.fflags = fflags_q;
      assign bits.wflags = wflags_q;
    end else begin : g_nofflags
      assign bits.fflags = '0;
      assign bits.wflags = 1'b0;
    end

    // 重定向：BJU/CSR 口保留 valid + taken + isMisPred；只有 CSR 口保留整个 redirect
    // BJU 口只保留 redirect_valid + taken + isMisPred（g_rlite）；CSR 口保留整个 redirect（g_rfull，含这两位）
    if (L.has_redir_lite) begin : g_rlite
      logic valid_q;
      always_ff @(posedge clock) if (in_valid) valid_q <= in_bits.redirect_valid;
      assign bits.redirect_valid = valid_q;
      if (!L.has_redir_full) begin : g_tm
        logic taken_q, mispred_q;
        always_ff @(posedge clock) if (in_valid) begin
          taken_q   <= in_bits.redirect.cfiUpdate.taken;
          mispred_q <= in_bits.redirect.cfiUpdate.isMisPred;
        end
        assign bits.redirect.cfiUpdate.taken     = taken_q;
        assign bits.redirect.cfiUpdate.isMisPred = mispred_q;
      end
    end else begin : g_norlite
      assign bits.redirect_valid              = 1'b0;
      assign bits.redirect.cfiUpdate.taken     = 1'b0;
      assign bits.redirect.cfiUpdate.isMisPred = 1'b0;
    end
    if (L.has_redir_full) begin : g_rfull
      redirect_t q;
      always_ff @(posedge clock) if (in_valid) q <= in_bits.redirect;
      assign bits.redirect.cfiUpdate.taken     = q.cfiUpdate.taken;
      assign bits.redirect.cfiUpdate.isMisPred = q.cfiUpdate.isMisPred;
      assign bits.redirect.isRVC        = q.isRVC;
      assign bits.redirect.robIdx       = q.robIdx;
      assign bits.redirect.ftqIdx       = q.ftqIdx;
      assign bits.redirect.ftqOffset    = q.ftqOffset;
      assign bits.redirect.level        = q.level;
      assign bits.redirect.interrupt    = q.interrupt;
      assign bits.redirect.cfiUpdate.pc          = q.cfiUpdate.pc;
      assign bits.redirect.cfiUpdate.pd          = q.cfiUpdate.pd;
      assign bits.redirect.cfiUpdate.ssp         = q.cfiUpdate.ssp;
      assign bits.redirect.cfiUpdate.sctr        = q.cfiUpdate.sctr;
      assign bits.redirect.cfiUpdate.TOSW        = q.cfiUpdate.TOSW;
      assign bits.redirect.cfiUpdate.TOSR        = q.cfiUpdate.TOSR;
      assign bits.redirect.cfiUpdate.NOS         = q.cfiUpdate.NOS;
      assign bits.redirect.cfiUpdate.topAddr     = q.cfiUpdate.topAddr;
      assign bits.redirect.cfiUpdate.folded_hist = q.cfiUpdate.folded_hist;
      assign bits.redirect.cfiUpdate.afhob       = q.cfiUpdate.afhob;
      assign bits.redirect.cfiUpdate.lastBrNumOH = q.cfiUpdate.lastBrNumOH;
      assign bits.redirect.cfiUpdate.ghr         = q.cfiUpdate.ghr;
      assign bits.redirect.cfiUpdate.histPtr     = q.cfiUpdate.histPtr;
      assign bits.redirect.cfiUpdate.specCnt     = q.cfiUpdate.specCnt;
      assign bits.redirect.cfiUpdate.br_hit      = q.cfiUpdate.br_hit;
      assign bits.redirect.cfiUpdate.jr_hit      = q.cfiUpdate.jr_hit;
      assign bits.redirect.cfiUpdate.sc_hit      = q.cfiUpdate.sc_hit;
      assign bits.redirect.cfiUpdate.predTaken   = q.cfiUpdate.predTaken;
      assign bits.redirect.cfiUpdate.target      = q.cfiUpdate.target;
      assign bits.redirect.cfiUpdate.shift       = q.cfiUpdate.shift;
      assign bits.redirect.cfiUpdate.addIntoHist = q.cfiUpdate.addIntoHist;
      assign bits.redirect.cfiUpdate.backendIGPF = q.cfiUpdate.backendIGPF;
      assign bits.redirect.cfiUpdate.backendIPF  = q.cfiUpdate.backendIPF;
      assign bits.redirect.cfiUpdate.backendIAF  = q.cfiUpdate.backendIAF;
      assign bits.redirect.fullTarget     = q.fullTarget;
      assign bits.redirect.satpFlush      = q.satpFlush;
      assign bits.redirect.isVlsException = q.isVlsException;
      assign bits.redirect.stFtqIdx       = q.stFtqIdx;
      assign bits.redirect.stFtqOffset    = q.stFtqOffset;
      assign bits.redirect.debug_runahead_checkpoint_id = q.debug_runahead_checkpoint_id;
      assign bits.redirect.debugIsCtrl    = q.debugIsCtrl;
      assign bits.redirect.debugIsMemVio  = q.debugIsMemVio;
    end else begin : g_norfull
      assign bits.redirect.isRVC        = 1'b0;
      assign bits.redirect.robIdx       = '0;
      assign bits.redirect.ftqIdx       = '0;
      assign bits.redirect.ftqOffset    = '0;
      assign bits.redirect.level        = 1'b0;
      assign bits.redirect.interrupt    = 1'b0;
      assign bits.redirect.cfiUpdate.pc          = '0;
      assign bits.redirect.cfiUpdate.pd          = '0;
      assign bits.redirect.cfiUpdate.ssp         = '0;
      assign bits.redirect.cfiUpdate.sctr        = '0;
      assign bits.redirect.cfiUpdate.TOSW        = '0;
      assign bits.redirect.cfiUpdate.TOSR        = '0;
      assign bits.redirect.cfiUpdate.NOS         = '0;
      assign bits.redirect.cfiUpdate.topAddr     = '0;
      assign bits.redirect.cfiUpdate.folded_hist = '0;
      assign bits.redirect.cfiUpdate.afhob       = '0;
      assign bits.redirect.cfiUpdate.lastBrNumOH = '0;
      assign bits.redirect.cfiUpdate.ghr         = '0;
      assign bits.redirect.cfiUpdate.histPtr     = '0;
      assign bits.redirect.cfiUpdate.specCnt     = '0;
      assign bits.redirect.cfiUpdate.br_hit      = 1'b0;
      assign bits.redirect.cfiUpdate.jr_hit      = 1'b0;
      assign bits.redirect.cfiUpdate.sc_hit      = 1'b0;
      assign bits.redirect.cfiUpdate.predTaken   = 1'b0;
      assign bits.redirect.cfiUpdate.target      = '0;
      assign bits.redirect.cfiUpdate.shift       = '0;
      assign bits.redirect.cfiUpdate.addIntoHist = 1'b0;
      assign bits.redirect.cfiUpdate.backendIGPF = 1'b0;
      assign bits.redirect.cfiUpdate.backendIPF  = 1'b0;
      assign bits.redirect.cfiUpdate.backendIAF  = 1'b0;
      assign bits.redirect.fullTarget     = '0;
      assign bits.redirect.satpFlush      = 1'b0;
      assign bits.redirect.isVlsException = 1'b0;
      assign bits.redirect.stFtqIdx       = '0;
      assign bits.redirect.stFtqOffset    = '0;
      assign bits.redirect.debug_runahead_checkpoint_id = '0;
      assign bits.redirect.debugIsCtrl    = 1'b0;
      assign bits.redirect.debugIsMemVio  = 1'b0;
    end

    // 异常向量：逐位按 exc_mask 保留（golden 每口只留 Rob 会看的位）
    for (genvar b = 0; b < EXC_N; b++) begin : g_exc
      if (L.exc_mask[b]) begin : g_y
        logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.exceptionVec[b];
        assign bits.exceptionVec[b] = q;
      end else begin : g_n
        assign bits.exceptionVec[b] = 1'b0;
      end
    end
    if (L.has_flushpipe) begin : g_flushpipe
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.flushPipe;
      assign bits.flushPipe = q;
    end else begin : g_noflushpipe
      assign bits.flushPipe = 1'b0;
    end
    if (L.has_satpflushpipe) begin : g_satpfp
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.satpFlushPipe;
      assign bits.satpFlushPipe = q;
    end else begin : g_nosatpfp
      assign bits.satpFlushPipe = 1'b0;
    end
    if (L.has_replay) begin : g_replay
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.replay;
      assign bits.replay = q;
    end else begin : g_noreplay
      assign bits.replay = 1'b0;
    end
    if (L.has_lqidx) begin : g_lqidx
      lqptr_t q; always_ff @(posedge clock) if (in_valid) q <= in_bits.lqIdx;
      assign bits.lqIdx = q;
    end else begin : g_nolqidx
      assign bits.lqIdx = '0;
    end
    if (L.has_sqidx) begin : g_sqidx
      sqptr_t q; always_ff @(posedge clock) if (in_valid) q <= in_bits.sqIdx;
      assign bits.sqIdx = q;
    end else begin : g_nosqidx
      assign bits.sqIdx = '0;
    end
    if (L.has_trigger) begin : g_trigger
      logic [3:0] q; always_ff @(posedge clock) if (in_valid) q <= in_bits.trigger;
      assign bits.trigger = q;
    end else begin : g_notrigger
      assign bits.trigger = '0;
    end
    if (L.has_predecode) begin : g_pd
      predecode_t q; always_ff @(posedge clock) if (in_valid) q <= in_bits.predecodeInfo;
      assign bits.predecodeInfo = q;
    end else begin : g_nopd
      assign bits.predecodeInfo = '0;
    end
    if (L.has_perfcnt) begin : g_perfcnt
      logic q; always_ff @(posedge clock) if (in_valid) q <= in_bits.debug_isPerfCnt;
      assign bits.debug_isPerfCnt = q;
    end else begin : g_noperfcnt
      assign bits.debug_isPerfCnt = 1'b0;
    end
    if (L.has_dbgmem) begin : g_dbgmem
      logic mmio_q, ncio_q; logic [47:0] paddr_q; logic [VADDR_W-1:0] vaddr_q;
      always_ff @(posedge clock) if (in_valid) begin
        mmio_q <= in_bits.debug_isMMIO; ncio_q <= in_bits.debug_isNCIO;
        paddr_q <= in_bits.debug_paddr; vaddr_q <= in_bits.debug_vaddr;
      end
      assign bits.debug_isMMIO = mmio_q;
      assign bits.debug_isNCIO = ncio_q;
      assign bits.debug_paddr  = paddr_q;
      assign bits.debug_vaddr  = vaddr_q;
    end else begin : g_nodbgmem
      assign bits.debug_isMMIO = 1'b0;
      assign bits.debug_isNCIO = 1'b0;
      assign bits.debug_paddr  = '0;
      assign bits.debug_vaddr  = '0;
    end
    if (L.has_dbglong) begin : g_dbglong
      logic            eliminatedMove_q;
      logic [XLEN-1:0] renameTime_q, dispatchTime_q, runahead_q, tlbFirstReqTime_q, tlbRespTime_q;
      seq_num_t        seqnum_q;
      always_ff @(posedge clock) if (in_valid) begin
        eliminatedMove_q  <= in_bits.debugInfo.eliminatedMove;
        renameTime_q      <= in_bits.debugInfo.renameTime;
        dispatchTime_q    <= in_bits.debugInfo.dispatchTime;
        runahead_q        <= in_bits.debugInfo.runahead_checkpoint_id;
        tlbFirstReqTime_q <= in_bits.debugInfo.tlbFirstReqTime;
        tlbRespTime_q     <= in_bits.debugInfo.tlbRespTime;
        seqnum_q          <= in_bits.debug_seqNum;
      end
      assign bits.debugInfo.eliminatedMove         = eliminatedMove_q;
      assign bits.debugInfo.renameTime             = renameTime_q;
      assign bits.debugInfo.dispatchTime           = dispatchTime_q;
      assign bits.debugInfo.runahead_checkpoint_id = runahead_q;
      assign bits.debugInfo.tlbFirstReqTime        = tlbFirstReqTime_q;
      assign bits.debugInfo.tlbRespTime            = tlbRespTime_q;
      assign bits.debug_seqNum                     = seqnum_q;
    end else begin : g_nodbglong
      assign bits.debugInfo.eliminatedMove         = 1'b0;
      assign bits.debugInfo.renameTime             = '0;
      assign bits.debugInfo.dispatchTime           = '0;
      assign bits.debugInfo.runahead_checkpoint_id = '0;
      assign bits.debugInfo.tlbFirstReqTime        = '0;
      assign bits.debugInfo.tlbRespTime            = '0;
      assign bits.debug_seqNum                     = '0;
    end
    if (L.has_vls) begin : g_vls
      vls_info_t q; always_ff @(posedge clock) if (in_valid) q <= in_bits.vls;
      assign bits.vls = q;
    end else begin : g_novls
      assign bits.vls = '0;
    end
    assign rob_i.writeback[i].bits = bits;

    // writebackNeedFlush：异常 | flushPipe | replay | trigger 进 debug 模式（各口按保留字段取）
    if (L.need_exc_gen) begin : g_needflush
      assign rob_i.writebackNeedFlush[i] = (|bits.exceptionVec) | bits.flushPipe
                                         | (L.has_replay  & bits.replay)
                                         | (L.has_trigger & (bits.trigger == TRIGGER_DMODE));
    end else begin : g_noneedflush
      assign rob_i.writebackNeedFlush[i] = 1'b0;
    end

    // writebackNums：同一拍里与本口同 robIdx 且都没被最老重定向冲掉的写回口数（含自己）
    if (L.nums_w != 0) begin : g_nums
      localparam int NW = L.nums_w;
      logic [WB_N-1:0] same;
      for (genvar k = 0; k < WB_N; k++) begin : g_same
        if (L.same_group[k]) begin : g_y
          assign same[k] = (io_in.wb[k].bits.robIdx == in_bits.robIdx)
                         & io_in.wb[k].valid & in_valid
                         & ~wb_killed_by_oldest[k] & ~wb_killed_by_oldest[i];
        end else begin : g_n
          assign same[k] = 1'b0;
        end
      end
      logic [NW-1:0] nums_q;
      always_ff @(posedge clock) if (in_valid) nums_q <= NW'($countones(same));
      assign rob_i.writebackNums[i] = WB_NUM_W'(nums_q);
    end else begin : g_nonums
      assign rob_i.writebackNums[i] = '0;
    end
  end

  // --------------------------------------------------------------------------
  // 3. 执行单元重定向：4 个带 redirect 的写回口里选最老的，打一拍给 RedirectGenerator
  // --------------------------------------------------------------------------
  logic [EXU_REDIR_N-1:0] exu_rd_valid;
  robptr_t                exu_rd_robIdx [EXU_REDIR_N];
  for (genvar j = 0; j < EXU_REDIR_N; j++) begin : g_exu_rd
    localparam int LANE = EXU_REDIR_LANE[j];
    assign exu_rd_valid[j]  = io_in.wb[LANE].valid & io_in.wb[LANE].bits.redirect_valid & ~wb_killed[LANE];
    assign exu_rd_robIdx[j] = io_in.wb[LANE].bits.redirect.robIdx;
  end
  // selectOldestRedirect：oneHot[i] = 所有 j<i 的口 (无效 或 i 比 j 老) 且 所有 j>i 的口 (无效 或 j 不比 i 老)
  logic [EXU_REDIR_N-1:0] exu_oldest_oh;
  for (genvar a = 0; a < EXU_REDIR_N; a++) begin : g_oh
    logic [EXU_REDIR_N-1:0] terms;
    for (genvar b = 0; b < EXU_REDIR_N; b++) begin : g_t
      if (b < a)       assign terms[b] = ~exu_rd_valid[b] | rob_is_after(exu_rd_robIdx[b], exu_rd_robIdx[a]);
      else if (b == a) assign terms[b] = exu_rd_valid[a];
      else             assign terms[b] = ~exu_rd_valid[b] | ~rob_is_after(exu_rd_robIdx[a], exu_rd_robIdx[b]);
    end
    assign exu_oldest_oh[a] = &terms;
  end
  // 丢掉 RedirectGenerator 不读的 pd / debugIsMemVio（golden 的那组寄存器没有它们）
  function automatic exu_redirect_t to_exu_redirect(redirect_t r);
    exu_redirect_t e;
    e.isRVC = r.isRVC; e.robIdx = r.robIdx; e.ftqIdx = r.ftqIdx; e.ftqOffset = r.ftqOffset;
    e.level = r.level; e.interrupt = r.interrupt;
    e.cfiUpdate.pc = r.cfiUpdate.pc; e.cfiUpdate.ssp = r.cfiUpdate.ssp; e.cfiUpdate.sctr = r.cfiUpdate.sctr;
    e.cfiUpdate.TOSW = r.cfiUpdate.TOSW; e.cfiUpdate.TOSR = r.cfiUpdate.TOSR; e.cfiUpdate.NOS = r.cfiUpdate.NOS;
    e.cfiUpdate.topAddr = r.cfiUpdate.topAddr; e.cfiUpdate.folded_hist = r.cfiUpdate.folded_hist;
    e.cfiUpdate.afhob = r.cfiUpdate.afhob; e.cfiUpdate.lastBrNumOH = r.cfiUpdate.lastBrNumOH;
    e.cfiUpdate.ghr = r.cfiUpdate.ghr; e.cfiUpdate.histPtr = r.cfiUpdate.histPtr; e.cfiUpdate.specCnt = r.cfiUpdate.specCnt;
    e.cfiUpdate.br_hit = r.cfiUpdate.br_hit; e.cfiUpdate.jr_hit = r.cfiUpdate.jr_hit; e.cfiUpdate.sc_hit = r.cfiUpdate.sc_hit;
    e.cfiUpdate.predTaken = r.cfiUpdate.predTaken; e.cfiUpdate.target = r.cfiUpdate.target;
    e.cfiUpdate.taken = r.cfiUpdate.taken; e.cfiUpdate.isMisPred = r.cfiUpdate.isMisPred;
    e.cfiUpdate.shift = r.cfiUpdate.shift; e.cfiUpdate.addIntoHist = r.cfiUpdate.addIntoHist;
    e.cfiUpdate.backendIGPF = r.cfiUpdate.backendIGPF; e.cfiUpdate.backendIPF = r.cfiUpdate.backendIPF;
    e.cfiUpdate.backendIAF = r.cfiUpdate.backendIAF;
    e.fullTarget = r.fullTarget; e.satpFlush = r.satpFlush; e.isVlsException = r.isVlsException;
    e.stFtqIdx = r.stFtqIdx; e.stFtqOffset = r.stFtqOffset;
    e.debug_runahead_checkpoint_id = r.debug_runahead_checkpoint_id; e.debugIsCtrl = r.debugIsCtrl;
    return e;
  endfunction
  // Mux1H：backendIAF/IPF/IGPF 只从 CSR 口取（非 CSR 口在 Chisel 里被硬写成 false）
  logic          exu_oldest_valid;
  exu_redirect_t exu_oldest_bits;
  predecode_t    exu_oldest_pd;
  logic          exu_oldest_is_csr;
  always_comb begin
    exu_oldest_valid = 1'b0;
    exu_oldest_bits  = '0;
    exu_oldest_pd    = '0;
    for (int j = 0; j < EXU_REDIR_N; j++) begin
      exu_redirect_t cand;
      cand = to_exu_redirect(io_in.wb[EXU_REDIR_LANE[j]].bits.redirect);
      if (!WB_LANE[EXU_REDIR_LANE[j]].has_csr) begin
        cand.cfiUpdate.backendIAF  = 1'b0;
        cand.cfiUpdate.backendIPF  = 1'b0;
        cand.cfiUpdate.backendIGPF = 1'b0;
      end
      cand.debugIsCtrl = 1'b1;   // exuRedirects.bits.debugIsCtrl := true.B
      exu_oldest_valid |= exu_oldest_oh[j] & exu_rd_valid[j];
      exu_oldest_bits  |= exu_oldest_oh[j] ? cand : '0;
      exu_oldest_pd    |= exu_oldest_oh[j] ? io_in.wb[EXU_REDIR_LANE[j]].bits.predecodeInfo : '0;
    end
  end
  assign exu_oldest_is_csr = (exu_oldest_oh == EXU_REDIR_CSR_OH);

  logic             exu_oldest_valid_q, exu_oldest_is_csr_q;
  exu_redirect_t    exu_oldest_bits_q;
  predecode_t       exu_oldest_pd_q;
  addr_trans_type_t instr_addr_trans_type_q;
  always_ff @(posedge clock) begin
    exu_oldest_valid_q      <= exu_oldest_valid;
    exu_oldest_bits_q       <= exu_oldest_bits;
    exu_oldest_is_csr_q     <= exu_oldest_is_csr;
    instr_addr_trans_type_q <= io_in.instrAddrTransType;
    exu_oldest_pd_q         <= exu_oldest_pd;
  end
  assign redirectgen_i.oldestExuRedirect_valid = exu_oldest_valid_q;
  assign redirectgen_i.oldestExuRedirect_bits  = exu_oldest_bits_q;
  assign redirectgen_i.oldestExuRedirectIsCSR  = exu_oldest_is_csr_q;
  assign redirectgen_i.instrAddrTransType      = instr_addr_trans_type_q;
  assign redirectgen_i.oldestExuOutPredecode   = exu_oldest_pd_q;

  // 给前端的 ftqIdxAhead(0)：最老 exu 重定向的 ftqIdx 提前一拍送去（Q8：只剩这一路）
  logic       ftq_ahead0_valid_q;
  logic [5:0] ftq_ahead0_value_q;
  always_ff @(posedge clock) begin
    ftq_ahead0_valid_q <= exu_oldest_valid;
    if (exu_oldest_valid) ftq_ahead0_value_q <= exu_oldest_bits.ftqIdx.value;
  end

  // --------------------------------------------------------------------------
  // 4. load 违例重定向（loadReplay）与 memPred / loadRedirect 的 pc 读
  // --------------------------------------------------------------------------
  logic           load_replay_valid_q;
  mem_violation_t load_replay_bits_q;
  logic [3:0]     mempred_offset_q;          // RegEnable(violation.stFtqOffset)
  logic [5:0]     load_redirect_pc_offset_q; // RegEnable((ftqOffset<<1) +& (flushItself ? 0 : isRVC ? 2 : 4))
  always_ff @(posedge clock or posedge reset)
    if (reset) load_replay_valid_q <= 1'b0; else load_replay_valid_q <= io_in.violation_valid;
  always_ff @(posedge clock) if (io_in.violation_valid) begin
    load_replay_bits_q        <= io_in.violation_bits;
    mempred_offset_q          <= io_in.violation_bits.stFtqOffset;
    load_redirect_pc_offset_q <= 6'({1'b0, io_in.violation_bits.ftqOffset, 1'b0})
                               + 6'(io_in.violation_bits.level ? 3'h0 : io_in.violation_bits.isRVC ? 3'h2 : 3'h4);
  end
  assign redirectgen_i.loadReplay_valid   = load_replay_valid_q;
  assign redirectgen_i.loadReplay_bits    = load_replay_bits_q;
  assign redirectgen_i.loadReplay_pc      = pcmem_o.rdata_startAddr[PCRD_REDIRECT] + VADDR_W'(load_redirect_pc_offset_q);
  assign redirectgen_i.memPredPcRead_data = pcmem_o.rdata_startAddr[PCRD_MEMPRED]  + VADDR_W'({mempred_offset_q, 1'b0});

  // --------------------------------------------------------------------------
  // 5. pcMem 读口分配（NamedIndexes）与写口打拍
  // --------------------------------------------------------------------------
  logic               newest_en_q;
  logic [VADDR_W-1:0] newest_target_q, newest_target_next_q;
  logic [5:0]         newest_ptr_q;
  logic [BRH_N-1:0]   need_newest_q;
  always_ff @(posedge clock) begin
    newest_en_q <= io_in.fromFtq.newest_entry_en;
    if (io_in.fromFtq.newest_entry_en) begin
      newest_target_q <= io_in.fromFtq.newest_entry_target;
      newest_ptr_q    <= io_in.fromFtq.newest_entry_ptr_value;
    end
    if (newest_en_q) newest_target_next_q <= newest_target_q;
    for (int b = 0; b < BRH_N; b++) need_newest_q[b] <= (io_in.fromDataPathFtqPtr[b] == newest_ptr_q);
  end

  logic [PCMEM_RD_N-1:0]      pcmem_ren;
  logic [PCMEM_RD_N-1:0][5:0] pcmem_raddr;
  always_comb begin
    pcmem_ren   = '0;
    pcmem_raddr = '0;
    pcmem_ren[PCRD_REDIRECT]   = io_in.violation_valid;
    pcmem_raddr[PCRD_REDIRECT] = io_in.violation_bits.ftqIdx.value;
    pcmem_ren[PCRD_MEMPRED]    = io_in.violation_valid;
    pcmem_raddr[PCRD_MEMPRED]  = io_in.violation_bits.stFtqIdx.value;
    pcmem_ren[PCRD_ROBFLUSH]   = rob_o.flushOut_valid;
    pcmem_raddr[PCRD_ROBFLUSH] = rob_o.flushOut_bits.ftqIdx.value;
    for (int b = 0; b < BRH_N; b++) begin
      pcmem_ren[PCRD_BJU_PC + b]    = io_in.fromDataPathValid[b];
      pcmem_raddr[PCRD_BJU_PC + b]  = io_in.fromDataPathFtqPtr[b];
      pcmem_ren[PCRD_BJU_TGT + b]   = io_in.fromDataPathValid[b];
      pcmem_raddr[PCRD_BJU_TGT + b] = io_in.fromDataPathFtqPtr[b] + 6'h1;   // 下一个 FTQ 项的起始地址
    end
    for (int l = 0; l < LDU_N; l++) begin
      pcmem_ren[PCRD_LOAD + l]   = io_in.fromDataPathValid[BRH_N + l];
      pcmem_raddr[PCRD_LOAD + l] = io_in.fromDataPathFtqPtr[BRH_N + l];
    end
    for (int t = 0; t < TRACE_GRP; t++) begin
      pcmem_ren[PCRD_TRACE + t]   = trace_o.toPcMem_valid[t];
      pcmem_raddr[PCRD_TRACE + t] = trace_o.toPcMem_ftqIdx_value[t];
    end
  end
  for (genvar b = 0; b < BRH_N; b++) begin : g_bju_tgt
    assign io_out.toDataPathTargetPC[b] = need_newest_q[b] ? newest_target_next_q : pcmem_o.rdata_startAddr[PCRD_BJU_TGT + b];
  end

  logic               pcmem_wen_q;
  logic [5:0]         pcmem_waddr_q;
  logic [VADDR_W-1:0] pcmem_wdata_q;
  always_ff @(posedge clock or posedge reset)
    if (reset) pcmem_wen_q <= 1'b0; else pcmem_wen_q <= io_in.fromFtq.pc_mem_wen;
  always_ff @(posedge clock) if (io_in.fromFtq.pc_mem_wen) begin
    pcmem_waddr_q <= io_in.fromFtq.pc_mem_waddr;
    pcmem_wdata_q <= io_in.fromFtq.pc_mem_wdata_startAddr;
  end
  assign pcmem_i.ren             = pcmem_ren;
  assign pcmem_i.raddr           = pcmem_raddr;
  assign pcmem_i.wen             = pcmem_wen_q;
  assign pcmem_i.waddr           = pcmem_waddr_q;
  assign pcmem_i.wdata_startAddr = pcmem_wdata_q;

  // trace：Trap/Xret 只出现在 block 0，取上一特权级
  assign io_out.trace_priv = (trace_o.block0_itype == 4'h1 | trace_o.block0_itype == 4'h2 | trace_o.block0_itype == 4'h3)
                           ? io_in.traceCSR.lastPriv : io_in.traceCSR.currentPriv;

  // --------------------------------------------------------------------------
  // 6. 发给前端 FTQ：提交信息、Rob flush（晚 6 拍）与 RedirectGenerator 重定向二选一
  // --------------------------------------------------------------------------
  logic s5_flush_ahead, s6_flush_valid_q, s5_csr_is_trap;
  assign s5_flush_ahead = delay_o.s5_flushFromRobValidAhead;
  assign s5_csr_is_trap = delay_o.s5_csrIsTrap;
  always_ff @(posedge clock or posedge reset)
    if (reset) s6_flush_valid_q <= 1'b0; else s6_flush_valid_q <= s5_flush_ahead;

  ftqptr_t            fe_flush_ftqIdx_q;
  logic [3:0]         fe_flush_ftqOffset_q;
  logic               fe_flush_satpFlush_q;
  logic [VADDR_W-1:0] s2_rob_flush_pc_q;     // 重放本条 → 本条 pc；flush 后续 → 下一条 pc
  always_ff @(posedge clock) if (s1_rob_flush_valid) begin
    fe_flush_ftqIdx_q    <= s1_rob_flush_bits.ftqIdx;
    fe_flush_ftqOffset_q <= s1_rob_flush_bits.ftqOffset;
    fe_flush_satpFlush_q <= s1_rob_flush_bits.satpFlush;
    s2_rob_flush_pc_q    <= s1_rob_flush_bits.level ? s1_rob_flush_pc
                          : s1_rob_flush_pc + VADDR_W'(s1_rob_flush_bits.isRVC ? 3'h2 : 3'h4);
  end
  logic [XLEN-1:0] flush_target;
  logic [XLEN-1:0] fe_flush_target_q;
  logic            fe_flush_iaf_q, fe_flush_ipf_q, fe_flush_igpf_q;
  assign flush_target = s5_csr_is_trap ? io_in.trapTarget.pc : {14'h0, s2_rob_flush_pc_q};
  always_ff @(posedge clock) if (s5_flush_ahead) begin
    fe_flush_target_q <= flush_target;
    fe_flush_iaf_q    <= s5_csr_is_trap & io_in.trapTarget.raiseIAF;
    fe_flush_ipf_q    <= s5_csr_is_trap & io_in.trapTarget.raiseIPF;
    fe_flush_igpf_q   <= s5_csr_is_trap & io_in.trapTarget.raiseIGPF;
  end

  // 提交信息：flushOut 那一拍的提交不告诉前端（带 flush 的提交对前端按异常处理）
  for (genvar c = 0; c < COMMIT_W; c++) begin : g_commit
    logic           is_commit, valid_q;
    commit_to_ftq_t bits_q;
    assign is_commit = rob_o.commits_commitValid[c] & rob_o.commits_isCommit & ~rob_o.flushOut_valid;
    always_ff @(posedge clock or posedge reset)
      if (reset) valid_q <= 1'b0; else valid_q <= is_commit;
    always_ff @(posedge clock) if (is_commit) bits_q <= rob_o.commits_info[c];
    assign io_out.toFtq.rob_commits[c].valid = valid_q;
    assign io_out.toFtq.rob_commits[c].bits  = bits_q;
  end

  assign io_out.toFtq.redirect_valid = s6_flush_valid_q | redirectgen_o.stage2_valid;
  assign io_out.toFtq.redirect.ftqIdx      = s6_flush_valid_q ? fe_flush_ftqIdx_q    : redirectgen_o.stage2_bits.ftqIdx;
  assign io_out.toFtq.redirect.ftqOffset   = s6_flush_valid_q ? fe_flush_ftqOffset_q : redirectgen_o.stage2_bits.ftqOffset;
  assign io_out.toFtq.redirect.level       = s6_flush_valid_q | redirectgen_o.stage2_bits.level;   // RedirectLevel.flush
  assign io_out.toFtq.redirect.cfiUpdate_pc     = s6_flush_valid_q ? '0 : redirectgen_o.stage2_bits.cfiUpdate.pc;
  assign io_out.toFtq.redirect.cfiUpdate_target = s6_flush_valid_q ? fe_flush_target_q[VADDR_W-1:0] : redirectgen_o.stage2_bits.cfiUpdate.target;
  assign io_out.toFtq.redirect.cfiUpdate_taken     = ~s6_flush_valid_q & redirectgen_o.stage2_bits.cfiUpdate.taken;
  assign io_out.toFtq.redirect.cfiUpdate_isMisPred = ~s6_flush_valid_q & redirectgen_o.stage2_bits.cfiUpdate.isMisPred;
  assign io_out.toFtq.redirect.cfiUpdate_backendIGPF = s6_flush_valid_q ? fe_flush_igpf_q : redirectgen_o.stage2_bits.cfiUpdate.backendIGPF;
  assign io_out.toFtq.redirect.cfiUpdate_backendIPF  = s6_flush_valid_q ? fe_flush_ipf_q  : redirectgen_o.stage2_bits.cfiUpdate.backendIPF;
  assign io_out.toFtq.redirect.cfiUpdate_backendIAF  = s6_flush_valid_q ? fe_flush_iaf_q  : redirectgen_o.stage2_bits.cfiUpdate.backendIAF;
  assign io_out.toFtq.redirect.satpFlush     = s6_flush_valid_q ? fe_flush_satpFlush_q : redirectgen_o.stage2_bits.satpFlush;
  assign io_out.toFtq.redirect.debugIsCtrl   = ~s6_flush_valid_q & redirectgen_o.stage2_bits.debugIsCtrl;
  assign io_out.toFtq.redirect.debugIsMemVio = ~s6_flush_valid_q & redirectgen_o.stage2_bits.debugIsMemVio;
  assign io_out.toFtq.ftqIdxSelOH        = {s6_flush_valid_q, redirectgen_o.stage2oldestOH & {2{~s6_flush_valid_q}}};
  assign io_out.toFtq.ftqIdxAhead0_valid = ftq_ahead0_valid_q & ~s1_rob_flush_valid & ~s5_flush_ahead;
  assign io_out.toFtq.ftqIdxAhead0_value = ftq_ahead0_value_q;

  // --------------------------------------------------------------------------
  // 7. 译码缓冲：decode 收不下的指令暂存 6 项，整体前移；缓冲非空时优先喂缓冲
  // --------------------------------------------------------------------------
  logic [DECODE_W-1:0] dbuf_valid_q;
  static_inst_t        dbuf_bits_q [DECODE_W];   // 寄存器体 + 保留的异常位拼回的完整视图（见 g_dbuf）
  logic [DECODE_W-1:0] dbuf_not_accept, fe_not_accept;
  logic [2:0]          dbuf_accept_num, fe_accept_num;   // 第一个未被接收的位置（全收下 = 6）

  // 前端 cfVec 装成 StaticInst：前端只带 1/2/12/20 四位异常、backendException 即 isFetchMalAddr
  static_inst_t fe_bits [DECODE_W];
  for (genvar i = 0; i < DECODE_W; i++) begin : g_fe
    always_comb begin
      fe_bits[i] = io_in.cfVec[i].bits;
      fe_bits[i].exceptionVec = io_in.cfVec[i].bits.exceptionVec & FRONTEND_EXC_BITS;
    end
    assign dbuf_not_accept[i] = dbuf_valid_q[i] & ~decode_o.in_ready[i];
    assign fe_not_accept[i]   = dbuf_valid_q[0] | (io_in.cfVec[i].valid & ~decode_o.in_ready[i]);
  end
  function automatic logic [2:0] first_not_accept(logic [DECODE_W-1:0] v);
    first_not_accept = 3'(DECODE_W);
    for (int i = DECODE_W - 1; i >= 0; i--) if (v[i]) first_not_accept = 3'(i);
  endfunction
  assign dbuf_accept_num = first_not_accept(dbuf_not_accept);
  assign fe_accept_num   = first_not_accept(fe_not_accept);

  // Q2：Chisel 的 Vec(6)(i + acceptNum) 下标按 3 位回绕，6/7 被 firtool 展开成"取第 0 项"：
  // 下面的选择循环默认取第 0 项，再用 k == 下标 覆盖（下标只用循环变量，避开 FMR_ELAB-147）。

  for (genvar i = 0; i < DECODE_W; i++) begin : g_dbuf
    logic shift_from_buf, load_from_fe, pop_last;
    logic [2:0] buf_k, fe_k;
    logic         buf_valid_sel, fe_valid_sel;
    static_inst_t buf_bits_sel, fe_bits_sel, dbuf_next;
    static_inst_body_t body_q;              // 除 exceptionVec 外的全部字段
    logic [EXC_N-1:0]  exc_q;               // 只有 DECODE_EXC_KEEP 里的位真有寄存器
    assign shift_from_buf = dbuf_valid_q[i] & (|dbuf_not_accept[DECODE_W-1:i]);
    assign load_from_fe   = ~dbuf_valid_q[0] & (|fe_not_accept[DECODE_W-1:i]);
    // 本项是这一拍被接收的最后一批：缓冲非空、本项有效、decode 收下且后面没有卡住的
    assign pop_last       = dbuf_valid_q[0] & dbuf_valid_q[i] & decode_o.in_ready[i] & ~(|dbuf_not_accept[DECODE_W-1:i]);
    assign buf_k = 3'(i) + dbuf_accept_num;   // 3 位回绕
    assign fe_k  = 3'(i) + fe_accept_num;
    always_comb begin
      buf_valid_sel = dbuf_valid_q[0];
      buf_bits_sel  = dbuf_bits_q[0];
      fe_valid_sel  = io_in.cfVec[0].valid;
      fe_bits_sel   = fe_bits[0];
      for (int k = 0; k < DECODE_W; k++) begin
        if (buf_k == 3'(k)) begin buf_valid_sel = dbuf_valid_q[k]; buf_bits_sel = dbuf_bits_q[k]; end
        if (fe_k  == 3'(k)) begin fe_valid_sel  = io_in.cfVec[k].valid; fe_bits_sel = fe_bits[k]; end
      end
      dbuf_next = shift_from_buf ? buf_bits_sel : fe_bits_sel;
    end
    always_ff @(posedge clock or posedge reset)
      if (reset) dbuf_valid_q[i] <= 1'b0;
      else if (decode_i.redirect | pop_last) dbuf_valid_q[i] <= 1'b0;
      else if (shift_from_buf) dbuf_valid_q[i] <= (dbuf_accept_num > 3'(DECODE_W - 1 - i)) ? 1'b0 : buf_valid_sel;
      else if (load_from_fe)   dbuf_valid_q[i] <= (fe_accept_num   > 3'(DECODE_W - 1 - i)) ? 1'b0 : fe_valid_sel;
    always_ff @(posedge clock)
      if (shift_from_buf | load_from_fe) body_q <= static_inst_body(dbuf_next);
    // 异常位逐位生成：DECODE_EXC_KEEP 之外的位（3/22）在 DecodeStage 入口没有端口，golden 没有这些寄存器
    for (genvar b = 0; b < EXC_N; b++) begin : g_exc
      if (DECODE_EXC_KEEP[b]) begin : g_y
        logic q;
        always_ff @(posedge clock) if (shift_from_buf | load_from_fe) q <= dbuf_next.exceptionVec[b];
        assign exc_q[b] = q;
      end else begin : g_n
        assign exc_q[b] = 1'b0;
      end
    end
    assign dbuf_bits_q[i] = static_inst_join(body_q, exc_q);
    // DecodeStage 入口：缓冲非空喂缓冲，否则喂前端
    assign decode_i.in[i].valid = dbuf_valid_q[0] ? dbuf_valid_q[i] : io_in.cfVec[i].valid;
    assign decode_i.in[i].bits  = dbuf_valid_q[i] ? dbuf_bits_q[i]  : fe_bits[i];
    assign io_out.cfVec_ready[i] = io_in.cfVec[0].valid & ~dbuf_valid_q[0] & io_in.cfVec[i].valid & ~decode_i.redirect;
  end
  assign io_out.canAccept        = ~dbuf_valid_q[0] | ~io_in.cfVec[0].valid;
  assign decode_i.backendCanAccept = io_out.canAccept;
  assign decode_i.redirect       = s1_s3_valid | pending_redirect_q;

  // csrCtrl 打一拍（decode / fusion / rob.wfi_enable 用）
  csr_ctrl_t csr_ctrl_q;
  always_ff @(posedge clock) csr_ctrl_q <= io_in.csrCtrl;
  assign decode_i.csrCtrl = csr_ctrl_q;
  assign rob_i.wfi_enable = csr_ctrl_q.wfi_enable;

  // --------------------------------------------------------------------------
  // 8. 快照：rename 出口打了 snapshot 的 uop 记一份 RobPtr 组，重定向时决定回滚到哪份
  // --------------------------------------------------------------------------
  logic [DECODE_W-1:0] rename_fire;
  logic                gen_snapshot;
  for (genvar i = 0; i < DECODE_W; i++) begin : g_rename_fire
    assign rename_fire[i] = pgc_o.in_ready[i] & rename_o.out_valid[i];
  end
  assign gen_snapshot = |(rename_fire & rename_o.out_snapshot);

  // 出队：deqPtr 指向的快照有效，且这一拍提交了它的第一条 uop
  logic snpt_deq;
  always_comb begin
    logic hit;
    hit = 1'b0;
    for (int c = 0; c < COMMIT_W; c++)
      hit |= rob_o.commits_commitValid[c] & (rob_o.commits_robIdx[c] == snpt_o.snapshots[snpt_o.deqPtr.value].robIdx[0]);
    snpt_deq = snpt_o.valids[snpt_o.deqPtr.value] & rob_o.commits_isCommit & hit;
  end

  // flushVec：快照 s 里每条 uop 要么"该冲掉"（自己或前面某条 >= 重定向点）要么不是 CFI
  logic [SNPT_N-1:0] flush_vec, flush_vec_next_q;
  for (genvar s = 0; s < SNPT_N; s++) begin : g_flushvec
    logic [DECODE_W-1:0] should_flush, should_flush_mask, ok;
    for (genvar j = 0; j < DECODE_W; j++) begin : g_j
      // robIdx >= redirect.robIdx || robIdx.value === redirect.robIdx.value
      assign should_flush[j] = (snpt_o.snapshots[s].robIdx[j].flag ^ s1_s3_bits.robIdx.flag
                                ^ (snpt_o.snapshots[s].robIdx[j].value >= s1_s3_bits.robIdx.value))
                             | (snpt_o.snapshots[s].robIdx[j].value == s1_s3_bits.robIdx.value);
      assign should_flush_mask[j] = |should_flush[j:0];
      assign ok[j] = should_flush_mask[j] | ~snpt_o.snapshots[s].isCFI[j];
    end
    assign flush_vec[s] = s1_s3_valid & (&ok);
    always_ff @(posedge clock or posedge reset)
      if (reset) flush_vec_next_q[s] <= 1'b0; else flush_vec_next_q[s] <= flush_vec[s] & snpt_o.valids[s];
  end

  // useSnpt / snptSelect：重定向点比快照头老（且不同 value）或"flushAfter 且正好等于"时可用
  function automatic logic snpt_usable(logic valid, robptr_t head, robptr_t rd, logic rd_level);
    return valid & ((rob_is_after(rd, head) & (rd.value != head.value)) | (~rd_level & (rd == head)));
  endfunction
  logic       use_snpt;
  logic [1:0] snpt_select;
  always_comb begin
    use_snpt = 1'b0;
    for (int s = 0; s < SNPT_N; s++)
      use_snpt |= snpt_usable(snpt_o.valids[s], snpt_o.snapshots[s].robIdx[0], s1_s3_bits.robIdx, s1_s3_bits.level);
    // Q3：MuxCase 依次试 enqPtr-1, enqPtr-2, enqPtr-3, enqPtr-4(=enqPtr)，2 位指针回绕，都不中给 0
    snpt_select = 2'h0;
    for (int k = SNPT_N; k >= 1; k--) begin
      logic [1:0] idx;
      idx = snpt_o.enqPtr.value - 2'(k);
      if (snpt_usable(snpt_o.valids[idx], snpt_o.snapshots[idx].robIdx[0], s1_s3_bits.robIdx, s1_s3_bits.level))
        snpt_select = idx;
    end
  end

  assign snpt_i.enq      = gen_snapshot;
  assign snpt_i.deq      = snpt_deq;
  assign snpt_i.flushVec = flush_vec_next_q;
  assign rob_i.snpt_useSnpt     = use_snpt;
  assign rob_i.snpt_snptSelect  = snpt_select;
  assign rob_i.snpt_snptDeq     = snpt_deq;
  assign rob_i.snpt_flushVec    = flush_vec_next_q;
  assign rename_i.snpt_useSnpt    = use_snpt;
  assign rename_i.snpt_snptSelect = snpt_select;
  assign rename_i.snpt_snptDeq    = snpt_deq;
  assign rename_i.snpt_flushVec   = flush_vec_next_q;
  assign rename_i.snptIsFull      = &snpt_o.valids;
  assign rename_i.snptLastEnq_valid = (snpt_o.enqPtr != snpt_o.deqPtr);            // !isEmpty
  assign rename_i.snptLastEnq_bits  = snpt_o.snapshots[snpt_o.enqPtr.value - 2'h1].robIdx[0];
  assign rat_i.snpt_snptEnq    = gen_snapshot;
  assign rat_i.snpt_snptDeq    = snpt_deq;
  assign rat_i.snpt_useSnpt    = use_snpt;
  assign rat_i.snpt_snptSelect = snpt_select;
  assign rat_i.snpt_flushVec   = flush_vec;          // RAT 收没打拍的
  for (genvar i = 0; i < DECODE_W; i++) begin : g_rat_upd
    assign rat_i.renameUpdates_valid[i] = rename_fire[i] & ~s1_s3_valid;
  end
  // renameOut.head.snapshot：快照队列没满时把全部 snapshot 位汇到第 0 路（其余路清 0）
  assign pgc_i.in0_snapshot = ~((snpt_o.enqPtr.flag != snpt_o.deqPtr.flag) & (snpt_o.enqPtr.value == snpt_o.deqPtr.value))
                            & (|(rename_o.out_valid & rename_o.out_snapshot));

  // --------------------------------------------------------------------------
  // 9. 融合译码：改写 rename/dispatch 入口的字段；清掉被融合的第二条
  // --------------------------------------------------------------------------
  assign fusion_i.disableFusion = csr_ctrl_q.singlestep | ~csr_ctrl_q.fusion_enable;
  for (genvar i = 0; i < DECODE_W; i++) begin : g_fusion_in
    assign fusion_i.in_valid[i] = decode_o.out_valid[i]
                                & ~((|decode_o.out_exceptionVec[i]) | (decode_o.out_trigger[i] != TRIGGER_NONE));
  end
  for (genvar i = 0; i < DECODE_W - 1; i++) begin : g_fusion_out
    logic       fv, same_ftq, cond1, cond2, cond3;
    logic [3:0] off_diff;
    assign fv       = fusion_o.out[i].valid;
    assign same_ftq = (pipe_o[i].ftqPtr_value == pipe_o[i+1].ftqPtr_value);
    assign off_diff = pipe_o[i+1].ftqOffset - pipe_o[i].ftqOffset;
    assign cond1 = same_ftq & (off_diff == 4'h1);
    assign cond2 = same_ftq & (off_diff == 4'h2);
    assign cond3 = ~same_ftq & (pipe_o[i+1].ftqOffset == 4'h0);
    assign decode_i.fusion[i] = fv & rename_fire[i];
    // Q4：fuType 改写成常量 35'h80（ALU）
    assign rename_i.in[i].fuType     = (fv & fusion_o.out[i].fuType_valid)   ? 35'h80                         : pipe_o[i].fuType;
    assign rename_i.in[i].fuOpType   = (fv & fusion_o.out[i].fuOpType_valid) ? fusion_o.out[i].fuOpType_bits  : pipe_o[i].fuOpType;
    assign rename_i.in[i].srcType_1  = (fv & fusion_o.out[i].src2Type_valid) ? 4'h1                           : pipe_o[i].srcType_1;
    assign rename_i.in[i].lsrc_1     = (fv & fusion_o.out[i].lsrc2_valid)    ? fusion_o.out[i].lsrc2_bits     : pipe_o[i].lsrc_1;
    assign rename_i.in[i].selImm     = (fv & fusion_o.out[i].selImm_valid)   ? fusion_o.out[i].selImm_bits    : pipe_o[i].selImm;
    assign rename_i.in[i].commitType = fv ? (cond1 ? 3'h4 : cond2 ? 3'h5 : {2'h3, ~cond3}) : pipe_o[i].commitType;
    assign dispatch_i.renameIn_fuType[i]   = rename_i.in[i].fuType;
    assign dispatch_i.renameIn_fuOpType[i] = rename_i.in[i].fuOpType;
  end
  // 最后一路没有融合改写
  assign rename_i.in[DECODE_W-1].fuType     = pipe_o[DECODE_W-1].fuType;
  assign rename_i.in[DECODE_W-1].fuOpType   = pipe_o[DECODE_W-1].fuOpType;
  assign rename_i.in[DECODE_W-1].srcType_1  = pipe_o[DECODE_W-1].srcType_1;
  assign rename_i.in[DECODE_W-1].lsrc_1     = pipe_o[DECODE_W-1].lsrc_1;
  assign rename_i.in[DECODE_W-1].selImm     = pipe_o[DECODE_W-1].selImm;
  assign rename_i.in[DECODE_W-1].commitType = pipe_o[DECODE_W-1].commitType;
  assign dispatch_i.renameIn_fuType[DECODE_W-1]   = pipe_o[DECODE_W-1].fuType;
  assign dispatch_i.renameIn_fuOpType[DECODE_W-1] = pipe_o[DECODE_W-1].fuOpType;
  // valid：第 0 路没有 clear；其余路被融合进前一条的清掉；dispatch 另外不收 move 消除的
  assign rename_i.in[0].valid        = pipe_o[0].out_valid;
  assign dispatch_i.renameIn_valid[0] = pipe_o[0].out_valid & ~pipe_o[0].isMove;
  for (genvar i = 1; i < DECODE_W; i++) begin : g_rename_valid
    assign rename_i.in[i].valid         = pipe_o[i].out_valid & ~fusion_o.clear[i];
    assign dispatch_i.renameIn_valid[i] = pipe_o[i].out_valid & ~fusion_o.clear[i] & ~pipe_o[i].isMove;
  end

  // --------------------------------------------------------------------------
  // 10. 访存依赖预测：译码 fire 那拍和下一拍把 foldpc 送 MemCtrl（golden 只保留前 2 路）
  // --------------------------------------------------------------------------
  for (genvar i = 0; i < MDP_N; i++) begin : g_mdp
    logic fire, fire_q;
    assign fire = pipe_o[i].in_ready & decode_o.out_valid[i];
    always_ff @(posedge clock or posedge reset)
      if (reset) fire_q <= 1'b0; else fire_q <= fire;
    assign memctrl_i.mdpFoldPcVecVld[i] = fire | fire_q;
    assign memctrl_i.mdpFlodPcVec[i]    = fire ? decode_i.in[i].bits.foldpc : pipe_o[i].foldpc;
  end

  // --------------------------------------------------------------------------
  // 11. Rob 入队：NewDispatch 的请求打一拍（valid 被 s1_s3 冲掉）
  // --------------------------------------------------------------------------
  logic      enq_valid_q [DECODE_W];
  dyn_inst_t enq_bits_q  [DECODE_W];   // 寄存器体 + 保留的 7 个异常位拼回的完整视图（见 g_enq）
  logic      enq_block_backward, enq_any_valid;
  for (genvar i = 0; i < DECODE_W; i++) begin : g_enq
    dyn_inst_body_t   body_q;
    logic [EXC_N-1:0] exc_q;
    always_ff @(posedge clock)
      enq_valid_q[i] <= dispatch_o.enqRob_req[i].valid & ~s1_s3_valid;
    always_ff @(posedge clock)
      if (dispatch_o.enqRob_req[i].valid) body_q <= dyn_inst_body(dispatch_o.enqRob_req[i].bits);
    // Rob 只看 ENQ_EXC_KEEP 的 7 位：其余位 golden 没有寄存器，这里也不生成
    for (genvar b = 0; b < EXC_N; b++) begin : g_exc
      if (ENQ_EXC_KEEP[b]) begin : g_y
        logic q;
        always_ff @(posedge clock) if (dispatch_o.enqRob_req[i].valid) q <= dispatch_o.enqRob_req[i].bits.exceptionVec[b];
        assign exc_q[b] = q;
      end else begin : g_n
        assign exc_q[b] = 1'b0;
      end
    end
    assign enq_bits_q[i] = dyn_inst_join(body_q, exc_q);
    assign rob_i.enq_req[i].valid = enq_valid_q[i];
    assign rob_i.enq_req[i].bits  = enq_bits_q[i];
  end
  always_comb begin
    enq_block_backward = 1'b0;
    enq_any_valid      = 1'b0;
    for (int i = 0; i < DECODE_W; i++) begin
      enq_block_backward |= enq_valid_q[i] & enq_bits_q[i].blockBackward & rob_o.enq_canAccept;
      enq_any_valid      |= enq_valid_q[i];
    end
  end
  assign dispatch_i.enqRob_canAccept = rob_o.enq_canAcceptForDispatch & ~enq_block_backward;
  assign dispatch_i.enqRob_isEmpty   = rob_o.enq_isEmpty & ~enq_any_valid;

  // singleStep 各打一拍给 rename / dispatch（golden 两个独立寄存器）
  logic rename_single_step_q, dispatch_single_step_q;
  always_ff @(posedge clock or posedge reset)
    if (reset) begin
      rename_single_step_q   <= 1'b0;
      dispatch_single_step_q <= 1'b0;
    end else begin
      rename_single_step_q   <= io_in.csrCtrl.singlestep;
      dispatch_single_step_q <= io_in.csrCtrl.singlestep;
    end
  assign rename_i.singleStep   = rename_single_step_q;
  assign dispatch_i.singleStep = dispatch_single_step_q;

  // --------------------------------------------------------------------------
  // 12. 杂项：vstart、retiredInstr、向量异常模块要的旧 pdest、perf/error 打两拍
  // --------------------------------------------------------------------------
  assign rob_i.vstartIsZero = (io_in.vstart == 8'h0);

  logic [6:0] retired_instr_q;
  always_ff @(posedge clock) retired_instr_q <= rob_o.retiredInstr;
  assign io_out.retiredInstr = retired_instr_q;

  // T: rat 收 rabCommit；T+1: rat 给出 oldPdest → 再打一拍出去（Q7：寄存器 8 位，输出 7 位）
  for (genvar r = 0; r < RAB_W; r++) begin : g_old_pdest
    logic              v0_valid_q, vec_valid_q, v0_out_valid_q, vec_out_valid_q;
    logic [PREG_W-1:0] v0_bits_q, vec_bits_q;
    always_ff @(posedge clock) begin
      v0_valid_q  <= rob_o.rabCommits_isCommit & rob_o.rabCommits_isWalk & rob_o.rabCommits_commitValid[r] & rob_o.rabCommits_v0Wen[r];
      vec_valid_q <= rob_o.rabCommits_isCommit & rob_o.rabCommits_isWalk & rob_o.rabCommits_commitValid[r] & rob_o.rabCommits_vecWen[r];
      v0_out_valid_q  <= v0_valid_q;
      vec_out_valid_q <= vec_valid_q;
      if (v0_valid_q)  v0_bits_q  <= rat_o.v0_old_pdest[r];
      if (vec_valid_q) vec_bits_q <= rat_o.vec_old_pdest[r];
    end
    assign io_out.v0OldVdPdest[r].valid  = v0_out_valid_q;
    assign io_out.v0OldVdPdest[r].bits   = v0_bits_q[PREG_W-2:0];
    assign io_out.vecOldVdPdest[r].valid = vec_out_valid_q;
    assign io_out.vecOldVdPdest[r].bits  = vec_bits_q[PREG_W-2:0];
  end

  logic [PERF_N-1:0][5:0] perf_q1, perf_q2;
  logic                   error_q1, error_q2;
  always_ff @(posedge clock) begin
    perf_q1  <= perf_in;
    perf_q2  <= perf_q1;
    error_q1 <= rob_o.error0;
    error_q2 <= error_q1;
  end
  assign io_out.perf   = perf_q2;
  assign io_out.error0 = error_q2;

endmodule

